use std::collections::BTreeMap;use artifactum_core::{provider_error,AcquireContext,AcquisitionPlan,ArtifactPath,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,ResolvedFile,ResolvedRevision,Resolution};use artifactum_provider_api::{apply_headers,bearer_headers,checked,client,encode_segment,plan,profile_value};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct NgcProvider;
fn api_url(base:&str,kind:&str,identity:&str,version:&str,file:&str)->artifactum_core::Result<String>{let parts=identity.split('/').collect::<Vec<_>>();if parts.len()<2||parts.len()>3{return Err(provider_error("ngc","identity must be <org>/<name> or <org>/<team>/<name>"));}let org=encode_segment(parts[0]);let name=encode_segment(parts[parts.len()-1]);let resource=if kind=="model"{"models"}else{"resources"};let prefix=if parts.len()==3{format!("{base}/org/{org}/team/{}/{resource}/{name}",encode_segment(parts[1]))}else{format!("{base}/org/{org}/{resource}/{name}")};Ok(format!("{prefix}/versions/{}/files/{}",encode_segment(version),file.split('/').map(encode_segment).collect::<Vec<_>>().join("/")))}
#[async_trait]impl ArtifactProvider for NgcProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"ngc".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["ngc".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<Resolution>{if c.offline{return Err(provider_error("ngc","cannot resolve while offline"));}let(kind,rest)=r.reference.locator().split_once(':').ok_or_else(||provider_error("ngc","expected ngc:model:<org[/team]/name>:<version>#<file>"))?;if !matches!(kind,"model"|"resource"){return Err(provider_error("ngc","kind must be model or resource"));}let(identity_file,file)=rest.split_once('#').ok_or_else(||provider_error("ngc","reference must include #<file>"))?;let(identity,version)=identity_file.rsplit_once(':').ok_or_else(||provider_error("ngc","reference must include :<version>"))?;let base=profile_value(c,"api_base").unwrap_or("https://api.ngc.nvidia.com/v2").trim_end_matches('/');let headers=bearer_headers(c.profile.as_ref(),"token_env","NGC_API_KEY");let url=api_url(base,kind,identity,version,file)?;let response=checked("ngc",apply_headers(client()?.head(&url),&headers).send().await.map_err(|e|provider_error("ngc",e))?).await?;let size=response.content_length();let media=response.headers().get(reqwest::header::CONTENT_TYPE).and_then(|v|v.to_str().ok()).map(str::to_owned);let rf=ResolvedFile{path:ArtifactPath::new(file)?,size,digests:Default::default(),media_type:media,source:serde_json::json!({"url":url})};Ok(Resolution{provider:"ngc".into(),canonical_ref:format!("ngc:{kind}:{identity}:{version}#{file}"),revision:Some(ResolvedRevision{id:version.into(),requested:r.revision.clone()}),files:vec![rf],provider_state:serde_json::Value::Null,metadata:BTreeMap::new()})}async fn prepare_acquisition(&self,f:&ResolvedFile,c:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{let url=f.source.get("url").and_then(|v|v.as_str()).ok_or_else(||provider_error("ngc","missing download URL"))?;let headers=bearer_headers(c.profile.as_ref(),"token_env","NGC_API_KEY");Ok(plan(url,headers))}}
pub fn provider()->NgcProvider{NgcProvider}
